(function(){
  function cls(n){ return Java.loadClass(n); }
  var Base = cls("com.merlinkitsune.astral_dice.item.sign.BaseSignItem");
  var Att = cls("com.merlinkitsune.astral_dice.component.ModAttachments");
  var Long = cls("java.lang.Long");
  var player = AutoJS.players()[0];
  var out = {};
  function beginLock(signId, endTick) {
    Att.setSignActiveLockSign(player, signId);
    Att.setSignActiveLockEnd(player, endTick);
    Att.setSignActiveLockGraceEnd(player, 0);
    Att.setSignActiveLockPlayed(player, false);
    Att.setSignActiveReductionPool(player, 0);
    Att.setSignActiveLockLastSeen(player, player.level().getGameTime());
    return true;
  }
  function clearAll() {
    Att.setSignActiveLockSign(player, "");
    Att.setSignActiveLockEnd(player, 0);
    Att.setSignActiveLockGraceEnd(player, 0);
    Att.setSignActiveLockPlayed(player, false);
    Att.setSignActiveReductionPool(player, 0);
    Att.setSignActiveCooldownEnd(player, 0);
    Att.setSignActiveMaxCooldown(player, 0);
    Att.setSignActiveLockLastSeen(player, 0);
  }
  clearAll();
  var now = Number(player.level().getGameTime());
  out.now = now;
  out.komachiConst = String(Base.KOMACHI_LOCK_ID);
  out.lockedAfterClear = Base.isSignActiveLocked(player);
  out.beginLockWritten = beginLock(Base.KOMACHI_LOCK_ID, 0);
  out.lockedAfterBegin = Base.isSignActiveLocked(player);
  out.lockSignAfterBegin = Att.getSignActiveLockSign(player);
  out.lockEndAfterBegin = Number(Att.getSignActiveLockEnd(player));
  out.playedAfterBegin = Att.getSignActiveLockPlayed(player);
  out.poolAfterBegin = Number(Att.getSignActiveReductionPool(player));
  out.lastSeenIsNow = Number(Att.getSignActiveLockLastSeen(player)) === now;
  Att.setSignActiveLockEnd(player, now + 1000);
  out.lockedFuture = Base.isSignActiveLocked(player);
  Att.setSignActiveLockEnd(player, now - 1);
  out.lockedPast = Base.isSignActiveLocked(player);
  Att.setSignActiveLockEnd(player, now - 1);
  Att.setSignActiveLockGraceEnd(player, now + 200);
  Att.setSignActiveLockPlayed(player, false);
  Base.tickSignActiveLock(player);
  out.signAfterGraceTick = Att.getSignActiveLockSign(player);
  out.graceAliveAfterTick = Number(Att.getSignActiveLockGraceEnd(player)) > now;
  out.cooldownAfterGraceTick = Number(Att.getSignActiveCooldownEnd(player));
  Att.setSignActiveLockEnd(player, now - 1);
  Att.setSignActiveLockGraceEnd(player, now - 1);
  Att.setSignActiveLockPlayed(player, false);
  Att.setSignActiveMaxCooldown(player, 1200);
  Att.setSignActiveReductionPool(player, 200);
  Base.tickSignActiveLock(player);
  out.signAfterEnd = Att.getSignActiveLockSign(player);
  out.lockEndAfterEnd = Number(Att.getSignActiveLockEnd(player));
  out.cooldownDelta = Number(Att.getSignActiveCooldownEnd(player)) - now;
  out.maxAfterEnd = Number(Att.getSignActiveMaxCooldown(player));
  out.poolAfterEnd = Number(Att.getSignActiveReductionPool(player));
  out.lockedAfterEnd = Base.isSignActiveLocked(player);
  clearAll();
  beginLock(Base.KOMACHI_LOCK_ID, 0);
  Att.setSignActiveLockEnd(player, 0);
  Att.setSignActiveLockGraceEnd(player, now - 1);
  Att.setSignActiveLockPlayed(player, true);
  Base.tickSignActiveLock(player);
  out.signAfterPlayed = Att.getSignActiveLockSign(player);
  out.graceAfterPlayed = Number(Att.getSignActiveLockGraceEnd(player));
  out.cooldownAfterPlayed = Number(Att.getSignActiveCooldownEnd(player));
  out.lockedAfterPlayed = Base.isSignActiveLocked(player);
  clearAll();
  out.lockedFinal = Base.isSignActiveLocked(player);
  out.signFinal = Att.getSignActiveLockSign(player);
  out.lastSeenFinal = Number(Att.getSignActiveLockLastSeen(player));
  return out;
})()
